import { pgTable, text, timestamp, boolean, jsonb, integer } from 'drizzle-orm/pg-core';

export const posts = pgTable('posts', {
  id: text('id').primaryKey(),
  title: text('title').notNull(),
  platforms: jsonb('platforms').notNull(), 
  pillarId: text('pillar_id').notNull(),
  format: text('format').notNull(),
  scheduledDate: text('scheduled_date').notNull(),
  scheduledTime: text('scheduled_time').notNull(),
  status: text('status').notNull(),
  caption: text('caption').notNull(),
  hashtags: jsonb('hashtags').notNull(), 
  hook: text('hook').notNull(),
  callToAction: text('call_to_action').notNull(),
  notes: text('notes').notNull(),
  assetLinks: jsonb('asset_links').notNull(), 
  checklist: jsonb('checklist').notNull(), 
  priority: text('priority').notNull(),
  isCollaboration: boolean('is_collaboration').notNull(),
  collabBrandName: text('collab_brand_name'),
  collabPayment: text('collab_payment'),
  metrics: jsonb('metrics'), 
  scriptContent: jsonb('script_content'), 
  createdAt: timestamp('created_at').notNull().defaultNow(),
  updatedAt: timestamp('updated_at').notNull().defaultNow(),
});

export const ideas = pgTable('ideas', {
  id: text('id').primaryKey(),
  title: text('title').notNull(),
  hook: text('hook').notNull(),
  pillarId: text('pillar_id').notNull(),
  suggestedFormat: text('suggested_format').notNull(),
  platforms: jsonb('platforms').notNull(), 
  notes: text('notes').notNull(),
  tags: jsonb('tags').notNull(), 
  createdAt: timestamp('created_at').notNull().defaultNow(),
});

export const settings = pgTable('settings', {
  id: integer('id').primaryKey(),
  creatorName: text('creator_name').notNull(),
  niche: text('niche').notNull(),
  weekStartsOnMonday: boolean('week_starts_on_monday').notNull(),
  accentColor: text('accent_color').notNull(),
  theme: text('theme').notNull(),
  weeklyTargetPosts: integer('weekly_target_posts'),
  platforms: jsonb('platforms').notNull(), 
  pillars: jsonb('pillars').notNull(), 
  templates: jsonb('templates').notNull(), 
  recurringSchedules: jsonb('recurring_schedules').notNull(), 
  hasCompletedOnboarding: boolean('has_completed_onboarding'),
  lastExportedAt: text('last_exported_at'),
});
