"use server";

import { db } from '@/db';
import { posts, ideas, settings } from '@/db/schema';
import { eq } from 'drizzle-orm';
import { PostItem, IdeaItem, UserSettings } from '@/types';

export async function getPosts(): Promise<PostItem[]> {
  const allPosts = await db.select().from(posts);
  return allPosts as unknown as PostItem[];
}

export async function createPost(post: PostItem) {
  await db.insert(posts).values(post as any);
}

export async function updatePostInDb(id: string, updates: Partial<PostItem>) {
  await db.update(posts).set({
    ...updates,
    updatedAt: new Date(),
  } as any).where(eq(posts.id, id));
}

export async function deletePostInDb(id: string) {
  await db.delete(posts).where(eq(posts.id, id));
}

export async function getIdeas(): Promise<IdeaItem[]> {
  const allIdeas = await db.select().from(ideas);
  return allIdeas as unknown as IdeaItem[];
}

export async function createIdea(idea: IdeaItem) {
  await db.insert(ideas).values(idea as any);
}

export async function updateIdeaInDb(id: string, updates: Partial<IdeaItem>) {
  await db.update(ideas).set(updates as any).where(eq(ideas.id, id));
}

export async function deleteIdeaInDb(id: string) {
  await db.delete(ideas).where(eq(ideas.id, id));
}

export async function getSettings(): Promise<UserSettings | null> {
  const userSettings = await db.select().from(settings).where(eq(settings.id, 1)).limit(1);
  return userSettings.length > 0 ? (userSettings[0] as unknown as UserSettings) : null;
}

export async function saveSettings(newSettings: UserSettings) {
  const existing = await getSettings();
  if (existing) {
    await db.update(settings).set(newSettings as any).where(eq(settings.id, 1));
  } else {
    await db.insert(settings).values({ id: 1, ...newSettings } as any);
  }
}
